    function scriptedSync(script) {
        var commands = [];
        var pr = loadPullRequestHelper();
        var result = pr.syncBranchWithBase({
            branchName: script.branchName || 'feature/CONF-1',
            baseBranch: script.baseBranch || 'main',
            workingDir: 'repo',
