/**
 * Extracts the trailing issue number from a ticket key (gh-737 → '737',
 * PROJ-123 → '123'). Returns null when the key carries no digits.
 */
function extractIssueNumber(ticketKey) {
    var m = /(\d+)\s*$/.exec(String(ticketKey || '').trim());
