            'git merge-base origin/main HEAD',
            'git status --porcelain --ignore-submodules=dirty',
            'git merge --no-edit origin/main',
            'git status --short',
            'git merge-base origin/main HEAD',
            'git ls-files --stage -- "src/app.js"',
            'git diff mb-sha HEAD -- "src/app.js"',
